import{_ as t,o as s,c as a,ah as n}from"./chunks/framework.ChH6X6u6.js";const u=JSON.parse('{"title":"Attendance and absences","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/vie-scolaire/presences-et-absences.md","filePath":"src/en/guide/vie-scolaire/presences-et-absences.md"}'),o={name:"en/guide/vie-scolaire/presences-et-absences.md"};function r(i,e,c,l,d,h){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="attendance-and-absences" tabindex="-1">Attendance and absences <a class="header-anchor" href="#attendance-and-absences" aria-label="Permalink to &quot;Attendance and absences&quot;">​</a></h1><p>This page covers taking daily attendance for classes and processing absence or lateness justifications submitted by families from their parent portal.</p><h2 id="take-daily-attendance" tabindex="-1">Take daily attendance <a class="header-anchor" href="#take-daily-attendance" aria-label="Permalink to &quot;Take daily attendance&quot;">​</a></h2><ol><li>Open <strong>School life → Attendance</strong>. The list shows all your classes, with a <strong>Today&#39;s roll call</strong> badge showing how many students have already been marked out of the total enrolled (for example &quot;18/24 taken&quot;).</li><li>Click <strong>Take attendance</strong> on the row for the relevant class.</li><li>The page defaults to the current day; change the date at the top of the page if you need to complete or correct attendance for another day.</li><li>For each student, set the <strong>Status</strong>: <strong>Present</strong>, <strong>Absent</strong> or <strong>Late</strong>. <ul><li>If you choose <strong>Late</strong>, enter the number of <strong>Minutes late</strong>.</li><li>Check <strong>Justified</strong> if the absence or lateness is already covered by a known reason, and add a free-text <strong>Note</strong> if needed (for example &quot;medical certificate provided&quot;).</li></ul></li><li>Click <strong>Save</strong> — the whole class&#39;s attendance is saved at once.</li></ol><h2 id="process-absence-justifications" tabindex="-1">Process absence justifications <a class="header-anchor" href="#process-absence-justifications" aria-label="Permalink to &quot;Process absence justifications&quot;">​</a></h2><p>Families submit their absence or lateness justifications from their parent portal; these appear in <strong>School life → Absence justifications</strong> with the status <strong>Pending</strong>.</p><ol><li>Open <strong>Absence justifications</strong>. The list shows, for each request, the student, their class, the date concerned, the reason given and its status. Click a row to open its detail.</li><li>If a document was attached, download it via <strong>Download document</strong> to review it before making a decision.</li><li>On a <strong>pending</strong> request, choose: <ul><li><strong>Approve</strong> — the justification is validated immediately, with no further input needed;</li><li><strong>Reject</strong> — a dialog asks you to enter a <strong>Reason for rejection</strong>, required, before confirming.</li></ul></li></ol><p>Once processed, the request moves to <strong>Approved</strong> or <strong>Rejected</strong>; a rejected justification shows its rejection reason directly in the list.</p>',8)])])}const f=t(o,[["render",r]]);export{u as __pageData,f as default};
